bool BND_ViewportInfo::Gen_DollyExtents(BND_BoundingBox cameraCoordinateBoundingBox, double border) {
  bool rc = false;
  if ((cameraCoordinateBoundingBox).IsValid())
  {
    if (border > 0.0 && border != 1.0 && RH3DM_RhinoMath::IsValidDouble(border))
    {
      double dx = ((cameraCoordinateBoundingBox).Max()).X() - ((cameraCoordinateBoundingBox).Min()).X();
      dx *= 0.5 * (border - 1.0);
      double dy = ((cameraCoordinateBoundingBox).Max()).Y() - ((cameraCoordinateBoundingBox).Min()).Y();
      dy *= 0.5 * (border - 1.0);
      auto pt = (cameraCoordinateBoundingBox).Max();
      (cameraCoordinateBoundingBox).set_Max(BND_Point3d((pt).X() + dx, (pt).Y() + dy, (pt).Z()));
      pt = (cameraCoordinateBoundingBox).Min();
      (cameraCoordinateBoundingBox).set_Min(BND_Point3d((pt).X() - dx, (pt).Y() - dy, (pt).Z()));
    }
    void* ptr_this = ((void*)(RH3DM_NonConst()));
    rc = RH3DM_R(ON_Viewport_DollyExtents(RH3DM_IP(ptr_this), RH3DM_Val((cameraCoordinateBoundingBox).Min()), RH3DM_Val((cameraCoordinateBoundingBox).Max())));
  }
  return rc;
}

