bool BND_ViewportInfo::Gen_ZoomToScreenRect_2(BND_TUPLE windowRectangle) const {
  return Gen_ZoomToScreenRect(RH3DM_RectLeft(windowRectangle), RH3DM_RectTop(windowRectangle), RH3DM_RectRight(windowRectangle), RH3DM_RectBottom(windowRectangle));
}

void BND_ViewportInfo::Gen_set_IsPerspectiveProjection(bool value) {
  void* ptr_this = ((void*)(RH3DM_NonConst()));
  ON_Viewport_SetProjection(RH3DM_IP(ptr_this), !value);
}

bool BND_ViewportInfo::Gen_DollyExtents_2(std::vector<const BND_GeometryBase*> geometry, double border) {
  auto world_2_camera = Gen_GetXform((RH3DM_CoordinateSystem)0, (RH3DM_CoordinateSystem)1);
  BND_BoundingBox cam_bbox = BND_BoundingBox::Unset();
  for (auto g : geometry)
  {
    auto bbox = (g)->Gen_GetBoundingBox(world_2_camera);
    (cam_bbox).Union(bbox);
  }
  return Gen_DollyExtents(cam_bbox, border);
}

BND_TUPLE BND_ViewportInfo::Gen_GetScreenPort_2() const {
  int near;
  int far;
  return Gen_GetScreenPort_out(near, far);
}

BND_TUPLE BND_ViewportInfo::Gen_ScreenPort() const {
  return Gen_GetScreenPort_2();
}

bool BND_ViewportInfo::Gen_SetScreenPort_3(BND_TUPLE windowRectangle) const {
  return Gen_SetScreenPort_2(windowRectangle, 0, 0);
}

void BND_ViewportInfo::Gen_set_ScreenPort(BND_TUPLE value) {
  Gen_SetScreenPort_3(value);
}

BND_TUPLE BND_ViewportInfo::Gen_GetScreenPortLocation() const {
  int left;
  int top;
  int right;
  int bottom;
  Gen_GetScreenPortLocation_out(left, top, right, bottom);
  BND_TUPLE rc = CreateTuple(4);
  SetTuple(rc, 0, left);
  SetTuple(rc, 1, top);
  SetTuple(rc, 2, right);
  SetTuple(rc, 3, bottom);
  return rc;
}

void BND_ViewportInfo::Gen_GetScreenPortLocation_out(int& left, int& top, int& right, int& bottom) const {
  auto rect = Gen_ScreenPort();
  left = RH3DM_RectLeft(rect);
  top = RH3DM_RectTop(rect);
  right = RH3DM_RectRight(rect);
  bottom = RH3DM_RectBottom(rect);
}

